import json

with open("scripts/data_crim_mcqs_part2.json", "r", encoding="utf-8") as f:
    mcqs = json.load(f)

def q(q_id, ch_id, top_id, text, opts, ans_idx, ans_letter, expl, breakdown, diff, prov, obj):
    return {
        "id": q_id,
        "subjectId": "law-criminal",
        "chapterId": ch_id,
        "topicId": top_id,
        "question": text,
        "options": opts,
        "answer": ans_idx,
        "answerLetter": ans_letter,
        "explanation": expl,
        "optionBreakdown": breakdown,
        "difficulty": diff,
        "provision": prov,
        "sourceUrl": "https://www.mha.gov.in",
        "verifiedDate": "2026-11-22",
        "applicableDate": "2026-11-22",
        "learningObjective": obj,
        "eligible": True,
        "status": "active"
    }

# -----------------------------------------------------------------------------
# top-crim-05-03: Abetment: Instigation, Conspiracy & Aid (10 MCQs: 141 to 150)
# -----------------------------------------------------------------------------
mcqs.append(q("mcq-crim-05-141", "ch-crim-05", "top-crim-05-03", "Under Section 45 BNS / Section 107 IPC, in how many statutory ways can a person abet the doing of a thing?", ["Two ways", "Three ways", "Four ways", "Five ways"], 1, "B", "Section 45 BNS / Section 107 IPC specifies three ways of abetment: (1) Instigation; (2) Conspiracy; (3) Intentional aid.", {"A": "Two is incomplete.", "B": "Correct; Instigation, Conspiracy, and Aiding.", "C": "Four is incorrect.", "D": "Five is incorrect."}, "Easy", "BNS Section 45 / IPC Section 107", "Identify the three statutory modes of abetment."))
mcqs.append(q("mcq-crim-05-142", "ch-crim-05", "top-crim-05-03", "A public officer is authorized by warrant from a Court of Justice to apprehend Z. B, knowing that fact and also that C is not Z, wilfully represents to the officer that C is Z, and thereby intentionally causes the apprehension of C. B abets the arrest by:", ["Conspiracy", "Instigation under Section 45 Explanation 1 BNS", "Passive silence", "Duress"], 1, "B", "Explanation 1 to Section 107 IPC / Section 45 BNS provides that wilful misrepresentation causing an act constitutes abetment by instigation.", {"A": "No agreement between B and officer.", "B": "Correct; instigation by wilful misrepresentation.", "C": "Active misrepresentation, not silence.", "D": "No threats used."}, "Medium", "BNS Section 45 Explanation 1", "Apply instigation by wilful misrepresentation."))
mcqs.append(q("mcq-crim-05-143", "ch-crim-05", "top-crim-05-03", "Can a person be guilty of abetting the abetment of an offence under Section 47 BNS / Section 108 Explanation 4 IPC?", ["No, abetment cannot be compounded", "Yes; the abetment of an abetment of an offence is itself an offence", "Only if the main offence is murder", "Only if the second abettor is present on the spot"], 1, "B", "Explanation 4 to Section 108 IPC / Section 47 BNS explicitly enacts: 'The abetment of an abetment of an offence is an offence.' (e.g. A instigates B to instigate C to murder Z).", {"A": "Statute permits it.", "B": "Correct; abetment of abetment is an offence.", "C": "Applies across all offences.", "D": "Presence not required."}, "Easy", "BNS Section 47 / IPC Section 108 Explanation 4", "Understand abetment of an abetment."))
mcqs.append(q("mcq-crim-05-144", "ch-crim-05", "top-crim-05-03", "A instigates B to murder C. B refuses to do so. What offence has A committed?", ["No offence because the act was not committed", "Abetment of murder under Section 46 BNS / Section 108 IPC", "Attempt to murder", "Criminal intimidation only"], 1, "B", "Under Explanation 2 to Section 108 IPC / Section 46 BNS, to constitute abetment, it is NOT necessary that the act abetted should be committed or that the effect should be caused.", {"A": "Abetment is complete upon instigation.", "B": "Correct; abetment is an inchoate offence complete upon instigation.", "C": "A did not attempt murder.", "D": "Substantive abetment of murder."}, "Medium", "BNS Section 46 Explanation 2", "Master the inchoate nature of abetment."))
mcqs.append(q("mcq-crim-05-145", "ch-crim-05", "top-crim-05-03", "A instigates a child of six years to set fire to a dwelling house. The child does not understand the nature of the act and sets fire. A is guilty of:", ["No offence because the child is doli incapax", "Abetment of mischief by fire, punishable as if the child were capable of committing the offence", "Only negligence", "Contempt of court"], 1, "B", "Under Explanation 3 to Section 108 IPC / Section 46 BNS, it is not necessary that the person abetted should be capable by law of committing an offence. The abettor is fully liable.", {"A": "Child's incapacity does not protect abettor.", "B": "Correct; abettor is liable though actor is legally immune.", "C": "Intentional instigation.", "D": "Not contempt."}, "Hard", "BNS Section 46 Explanation 3", "Apply abetment of person incapable of committing crime."))
mcqs.append(q("mcq-crim-05-146", "ch-crim-05", "top-crim-05-03", "Under Section 50 BNS / Section 111 IPC, an abettor is liable for a different act committed by the person abetted IF:", ["The act done was a probable consequence of the abetment, and was committed under the influence of the instigation", "The abettor was related to the actor", "The actor used the abettor's car", "The victim was a public servant"], 0, "A", "Under Section 50 BNS / Section 111 IPC (Doctrine of Probable Consequence), the abettor is liable for a different act if it was a probable consequence of the abetment.", {"A": "Correct; probable consequence doctrine.", "B": "Kinship irrelevant.", "C": "Vehicle irrelevant.", "D": "Victim status irrelevant."}, "Medium", "BNS Section 50 / IPC Section 111", "Master the probable consequence doctrine in abetment."))
mcqs.append(q("mcq-crim-05-147", "ch-crim-05", "top-crim-05-03", "A instigates B to burn Z's house. B sets fire to the house and at the same time commits theft of property there. Is A liable for the theft?", ["Yes, A instigated B", "No, because the theft was not a probable consequence of burning the house", "Yes, under joint liability", "Yes, if A accepted a share of the stolen property"], 1, "B", "Under Illustration (a) to Section 111 IPC / Section 50 BNS, A is guilty of abetting the burning of the house, but is not guilty of abetting the theft, for the theft was a distinct act and not a probable consequence of the burning.", {"A": "Overstates liability.", "B": "Correct; theft is distinct, not a probable consequence of burning.", "C": "No common intention for theft.", "D": "Receiving stolen property is separate S. 317."}, "Hard", "BNS Section 50 Illustration (a)", "Apply Section 111 probable consequence illustration."))
mcqs.append(q("mcq-crim-05-148", "ch-crim-05", "top-crim-05-03", "Under Section 52 BNS / Section 113 IPC, when an act is abetted and a different effect is caused, the abettor is liable for the effect caused if:", ["The abettor knew that the act abetted was likely to cause that effect", "The victim was elderly", "The offence took place at night", "The weapon was licensed"], 0, "A", "Section 52 BNS / Section 113 IPC provides that the abettor is liable for the different effect caused in the same manner as if he had directly intended it, if he knew the act was likely to cause that effect.", {"A": "Correct; foresight of likelihood of effect.", "B": "Age irrelevant.", "C": "Time irrelevant.", "D": "License irrelevant."}, "Medium", "BNS Section 52 / IPC Section 113", "Understand different effect liability in abetment."))
mcqs.append(q("mcq-crim-05-149", "ch-crim-05", "top-crim-05-03", "What is the consequence under Section 53 BNS / Section 114 IPC when an abettor who would be punishable is present when the act is committed?", ["He is treated as an accessory after the fact", "He shall be deemed to have committed such act or offence himself", "He gets half the punishment", "He is acquitted"], 1, "B", "Section 53 BNS / Section 114 IPC creates a statutory fiction: whenever an abettor is present when the act is committed, he shall be deemed to have committed the offence himself.", {"A": "Not accessory.", "B": "Correct; deemed to have committed offence himself.", "C": "Full penalty.", "D": "Full liability."}, "Easy", "BNS Section 53 / IPC Section 114", "Recall deemed principal rule in abetment presence."))
mcqs.append(q("mcq-crim-05-150", "ch-crim-05", "top-crim-05-03", "A gives poison to B with instructions to administer it to C. B takes the poison to C's house, but throws it in the river instead. What is A's liability?", ["A has committed no offence because no poison was given to C", "A is guilty of abetment of murder", "A is guilty of simple hurt", "A is guilty of nuisance"], 1, "B", "Abetment is an independent inchoate offence; instigation and providing poison completes the abetment of murder regardless of B's subsequent abandonment.", {"A": "Abetment does not depend on commission.", "B": "Correct; abetment of murder complete.", "C": "No hurt caused.", "D": "Severe crime, not nuisance."}, "Medium", "Queen v. Mostapha, (1870) 5 MHC 189", "Apply inchoate nature of abetment to abandoned crime."))

