# top-crim-05-04: Criminal Conspiracy (10 MCQs: 151 to 160)
# -----------------------------------------------------------------------------
mcqs.append(q("mcq-crim-05-151", "ch-crim-05", "top-crim-05-04", "Which provision of BNS 2023 replaces Sections 120A and 120B of the Indian Penal Code, 1860 for Criminal Conspiracy?", ["Section 3(5)", "Section 61", "Section 111", "Section 189"], 1, "B", "Section 61 BNS consolidates the definition (S. 120A) and punishment (S. 120B) of Criminal Conspiracy into a single section.", {"A": "Section 3(5) is S. 34 IPC.", "B": "Correct; Section 61 BNS is Criminal Conspiracy.", "C": "Section 111 is Organised crime.", "D": "Section 189 is Unlawful assembly."}, "Easy", "BNS Section 61 vs IPC Sections 120A/120B", "Map BNS Section 61 for Criminal Conspiracy."))
mcqs.append(q("mcq-crim-05-152", "ch-crim-05", "top-crim-05-04", "Under Section 61(1) BNS / Section 120A IPC, when two or more persons agree to do an ILLEGAL ACT (which is an offence), is an overt act necessary to complete the conspiracy?", ["Yes, an overt act must always be proved", "No; bare agreement itself constitutes the offence of criminal conspiracy without any overt act", "Yes, money must be exchanged", "Yes, weapon must be procured"], 1, "B", "The proviso to Section 120A IPC / Section 61(1) BNS provides that no overt act is necessary where the agreement is to commit an offence; the bare agreement itself is the crime.", {"A": "Overt act needed only if act is not an offence.", "B": "Correct; bare agreement to commit an offence is complete conspiracy.", "C": "Money not required.", "D": "Weapon not required."}, "Medium", "BNS Section 61(1) Proviso", "Master agreement as the gist of conspiracy."))
mcqs.append(q("mcq-crim-05-153", "ch-crim-05", "top-crim-05-04", "When is an OVERT ACT required to constitute criminal conspiracy under Section 61(1) BNS / Section 120A IPC?", ["When the agreement is to commit murder", "When the agreement is to do an act which is not an offence, but is an illegal act or an act by illegal means", "When the conspirators are more than ten", "In cyber-crimes only"], 1, "B", "The proviso stipulates: 'Provided that no agreement except an agreement to commit an offence shall amount to a criminal conspiracy unless some act besides the agreement is done...'.", {"A": "Offences need no overt act.", "B": "Correct; non-offence illegal acts require an overt act.", "C": "Number of conspirators doesn't change rule.", "D": "General rule across all conspiracies."}, "Hard", "BNS Section 61(1) Proviso", "Distinguish offence conspiracy from non-offence illegal conspiracy."))
mcqs.append(q("mcq-crim-05-154", "ch-crim-05", "top-crim-05-04", "In State (NCT of Delhi) v. Navjot Sandhu (Parliament Attack Case, 2005), the Supreme Court affirmed that criminal conspiracy is:", ["A substantive offence that is continuous in nature from the time of agreement until completion or abandonment", "A minor misdemeanour requiring proof by eyewitnesses of the secret meeting", "Admissible only if written minutes exist", "Punishable only if treason is committed"], 0, "A", "The Supreme Court held conspiracy is a continuing offence hatched in secrecy; direct evidence is rarely available and agreement is inferred from circumstantial acts.", {"A": "Correct; continuing substantive offence.", "B": "Not minor; secret meetings rarely have direct witnesses.", "C": "Conspirators do not keep minutes.", "D": "Applies across offences."}, "Hard", "(2005) 11 SCC 600", "Apply Navjot Sandhu criminal conspiracy doctrine."))
mcqs.append(q("mcq-crim-05-155", "ch-crim-05", "top-crim-05-04", "What is the punishment for criminal conspiracy to commit an offence punishable with death, life imprisonment, or rigorous imprisonment for 2+ years under S. 61(2) BNS / S. 120B(1) IPC?", ["Simple imprisonment up to 6 months", "Punished in the same manner as if he had abetted such offence", "Fine of Rs 5,000 only", "Community service"], 1, "B", "Section 61(2)(a) BNS / Section 120B(1) IPC provides that the conspirator shall be punished in the same manner as if he had abetted such offence.", {"A": "6 months is for minor offences under clause (b).", "B": "Correct; punished as an abettor of the offence.", "C": "Not fine only.", "D": "Severe crime, not community service."}, "Easy", "BNS Section 61(2)(a) / IPC Section 120B(1)", "Recall penalty for serious criminal conspiracies."))
mcqs.append(q("mcq-crim-05-156", "ch-crim-05", "top-crim-05-04", "What is the minimum number of persons required to form a criminal conspiracy under Section 61 BNS / Section 120A IPC?", ["One person", "Two persons", "Three persons", "Five persons"], 1, "B", "A person cannot conspire with himself; Section 61 BNS / Section 120A IPC explicitly requires 'two or more persons'.", {"A": "Conspiracy requires agreement between two or more.", "B": "Correct; minimum two persons.", "C": "Three is not minimum.", "D": "Five is for unlawful assembly."}, "Easy", "BNS Section 61(1)", "Recall minimum membership for conspiracy."))
mcqs.append(q("mcq-crim-05-157", "ch-crim-05", "top-crim-05-04", "In Topandas v. State of Bombay (1955), four persons were charged with criminal conspiracy. Three were acquitted on trial. Can the conviction of the sole fourth accused for conspiracy stand?", ["Yes, if he was the mastermind", "No; one person alone cannot be convicted of criminal conspiracy when all other alleged conspirators have been acquitted", "Yes, if he confesses", "Yes, on payment of fine"], 1, "B", "The Supreme Court held that it is an established principle of law that one person cannot be convicted of conspiracy where all co-accused have been acquitted, as an agreement requires at least two minds.", {"A": "Cannot agree with oneself.", "B": "Correct; sole accused cannot be convicted of conspiracy.", "C": "Legal impossibility.", "D": "Not fine."}, "Hard", "AIR 1956 SC 33", "Apply Topandas acquittal of co-conspirators rule."))
mcqs.append(q("mcq-crim-05-158", "ch-crim-05", "top-crim-05-04", "Is it necessary that every conspirator must actively participate in every single act done in execution of the conspiracy?", ["Yes, all conspirators must be physically present at all acts", "No; once common design is established, every conspirator is liable for acts done by any co-conspirator in execution of the common plan", "Only the conspirator who supplied weapons is liable", "Only the person who struck the fatal blow is liable"], 1, "B", "In Yash Pal Mittal v. State of Punjab, the Supreme Court confirmed that it is not necessary that each conspirator must know every detail or participate in every stage.", {"A": "Presence not required.", "B": "Correct; agency principle binds all conspirators.", "C": "Too narrow.", "D": "Fatal striker is not sole liable person."}, "Medium", "(1977) 4 SCC 540", "Master agency liability in criminal conspiracy."))
mcqs.append(q("mcq-crim-05-159", "ch-crim-05", "top-crim-05-04", "What is the punishment for criminal conspiracy to commit an offence NOT punishable with death, life, or 2+ years under S. 61(2)(b) BNS / S. 120B(2) IPC?", ["Imprisonment up to six (6) months, or fine, or both", "Imprisonment up to 2 years", "Life imprisonment", "Community service for 2 years"], 0, "A", "Under Section 61(2)(b) BNS / Section 120B(2) IPC, conspiracy for minor offences is punishable with imprisonment up to six months, or fine, or both.", {"A": "Correct; up to six months or fine or both.", "B": "Incorrect.", "C": "Disproportionate.", "D": "Not code penalty."}, "Easy", "BNS Section 61(2)(b)", "Recall penalty for minor conspiracies."))
mcqs.append(q("mcq-crim-05-160", "ch-crim-05", "top-crim-05-04", "How does Criminal Conspiracy under Section 61 BNS differ from Abetment by Conspiracy under Section 45(Secondly) BNS?", ["Section 61 requires an overt act; Section 45 does not", "In Section 61 bare agreement to commit offence is punishable; in Section 45 abetment, an act or illegal omission must take place in pursuance of the conspiracy", "Section 61 applies only to public servants", "Section 45 is a civil wrong"], 1, "B", "In Pramatha Nath Talukdar v. Saroj Ranjan Sarkar, the Supreme Court held: under Section 107/45 abetment by conspiracy, an act or illegal omission must occur in pursuance; under Section 120A/61, bare agreement to commit an offence is substantive crime.", {"A": "Inverts the rule.", "B": "Correct; Section 61 bare agreement vs Section 45 overt act in pursuance.", "C": "Applies generally.", "D": "Abetment is criminal."}, "Hard", "AIR 1962 SC 876", "Distinguish substantive conspiracy from abetment by conspiracy."))

